import{calculator,CalcError,has,pos,frac,nonneg,num,dflt}from './core.js?ver=43e079bb5e';
export const solar_forecast=calculator((i,d)=>{const kwp=pos(i,'kwp');const city=String(i.city??'').trim().toLowerCase();const c=d?.cities?.[city];if(!c||!(c.yield>0))throw new CalcError('city_unknown','city');const pr=frac(i,'pr',dflt(d,'pr'));const typical_units=kwp*c.yield;const out={kwp,city,city_name:city.replace(/\b\w/g,(m)=>m.toUpperCase()),pr,no_loss_overstatement:1/pr-1,typical_psh:c.psh,typical_units};if(Array.isArray(i.gti_wm2)&&i.gti_wm2.length){if(i.gti_wm2.length>48)throw new CalcError('forecast_invalid','gti_wm2');const hours=i.gti_wm2.map((w)=>num({gti_wm2:w},'gti_wm2',{min:0,max:dflt(d,'forecast_max_wm2'),code:'forecast_invalid'}));const day_whm2=hours.reduce((s,w)=>s+w,0);if(day_whm2>dflt(d,'forecast_max_day_whm2'))throw new CalcError('forecast_invalid','gti_wm2');const psh=day_whm2/1000;const units=kwp*psh*pr;const pct=(psh/c.psh)*100;const band=dflt(d,'forecast_sky_bands').find((b)=>pct>=b.min_pct);const date=typeof i.forecast_date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(i.forecast_date)?i.forecast_date:null;Object.assign(out,{source:'forecast',psh,units,kwh_per_kwp:psh*pr,pct_of_typical:pct,sky:band?band.label:'Overcast or rain',day_label:date?`Forecast for ${date}`:'Forecast'},date?{forecast_date:date}:{});}else{Object.assign(out,{source:'typical',psh:c.psh,units:typical_units,kwh_per_kwp:c.yield,pct_of_typical:100,sky:'Typical day',day_label:'Typical day (long-term average)'});}
if(has(i,'tariff')){out.tariff=nonneg(i,'tariff');out.rs_value=out.units*out.tariff;}
return out;});
